async function studentPortal(){if(!await requireUser())return;if(state.profile?.role==='admin')return go('admin');const {data:ens}=await sb.from('enrollments').select('*,courses(*)').eq('user_id',state.session.user.id).in('status',['active','completed']).order('created_at',{ascending:false});const {data:events}=await sb.from('calendar_events').select('*').gte('starts_at',new Date().toISOString()).order('starts_at').limit(8);shell(`<main class="portal"><aside class="sidebar"><div class="side-title"><span class="brandmark" style="border-color:#fff">WT</span><div><b>Área do aluno</b><div class="hint" style="color:#aaa">${esc(state.profile?.full_name||state.session.user.email)}</div></div></div><nav><button class="active" data-sview="home">Visão geral</button><button data-sview="courses">Meus cursos</button><button data-sview="agenda">Agenda</button><button data-sview="doubts">Dúvidas</button><button data-sview="forum">Fórum</button><button data-sview="notifications">Notificações</button></nav><button class="logout" id="logoutSide">Sair</button></aside><section class="portal-main" id="studentMain"></section></main>`);document.querySelector('#logoutSide').onclick=logout;document.querySelectorAll('[data-sview]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-sview]').forEach(x=>x.classList.toggle('active',x===b));state.studentView=b.dataset.sview;renderStudentView(ens||[],events||[])});renderStudentView(ens||[],events||[])}
async function renderStudentView(ens,events){const el=document.querySelector('#studentMain');if(state.studentView==='home'){el.innerHTML=`<div class="dash-head"><div><div class="eyebrow">Área do aluno</div><h1>Olá, ${esc((state.profile?.full_name||'Aluno').split(' ')[0])}</h1></div></div><div class="stat-grid"><div class="stat"><b>${ens.length}</b><span>Cursos ativos</span></div><div class="stat"><b>${events.length}</b><span>Próximos eventos</span></div><div class="stat"><b>WT</b><span>Ambiente de estudo</span></div><div class="stat"><b>80h</b><span>Curso ABA</span></div></div><div class="panel"><h2>Continuar estudando</h2>${ens.length?ens.map(e=>`<div class="material"><div><b>${esc(e.courses.title)}</b><div class="hint">${esc(e.status)} · acesso ${e.access_ends_at?`até ${dateTime(e.access_ends_at)}`:'sem data final'}</div></div><button class="btn small" data-learn="${e.course_id}">Entrar</button></div>`).join(''):'<div class="empty">Você ainda não possui cursos ativos. <a href="#cursos">Conheça os cursos disponíveis.</a></div>'}</div>`;document.querySelectorAll('[data-learn]').forEach(b=>b.onclick=()=>openLearning(b.dataset.learn));return}if(state.studentView==='courses'){el.innerHTML=`<div class="dash-head"><div><div class="eyebrow">Formação</div><h1>Meus cursos</h1></div></div><div class="cards">${ens.map(e=>`<article class="card"><div class="eyebrow">${e.courses.workload_hours} horas</div><h3>${esc(e.courses.title)}</h3><p>Status: ${esc(e.status)}</p><div class="bottom"><button class="btn" data-learn="${e.course_id}">Entrar no curso</button></div></article>`).join('')||'<div class="empty">Nenhum curso ativo.</div>'}</div>`;document.querySelectorAll('[data-learn]').forEach(b=>b.onclick=()=>openLearning(b.dataset.learn));return}if(state.studentView==='agenda'){el.innerHTML=`<div class="dash-head"><div><div class="eyebrow">Agenda</div><h1>Próximas aulas e eventos</h1></div></div><div class="panel">${events.length?events.map(ev=>`<div class="material"><div><b>${esc(ev.title)}</b><div class="hint">${dateTime(ev.starts_at)}</div></div>${ev.meeting_url?`<a class="btn small" href="${esc(ev.meeting_url)}" target="_blank">Entrar</a>`:''}</div>`).join(''):'<div class="empty">Nenhum evento agendado.</div>'}</div>`;return}if(state.studentView==='doubts'){const {data}=await sb.from('doubts').select('*,courses(title),lessons(title)').eq('user_id',state.session.user.id).order('created_at',{ascending:false});el.innerHTML=`<div class="dash-head"><div><div class="eyebrow">Dúvidas</div><h1>Minhas perguntas</h1></div></div><form class="panel" id="doubtForm"><div class="form-grid"><div class="field"><label>Curso</label><select id="dCourse">${ens.map(e=>`<option value="${e.course_id}">${esc(e.courses.title)}</option>`).join('')}</select></div><div class="field"><label>Assunto</label><input id="dSubject" required></div><div class="field wide"><label>Pergunta</label><textarea id="dBody" required></textarea></div></div><button class="btn">Enviar dúvida</button></form><div class="panel">${data?.length?data.map(d=>`<div class="forum-thread"><div class="eyebrow">${esc(d.status)}</div><h4>${esc(d.subject)}</h4><p>${esc(d.body)}</p>${d.official_reply?`<p><b>Resposta oficial — Walef Teixeira:</b><br>${esc(d.official_reply)}</p>`:''}</div>`).join(''):'<div class="empty">Nenhuma dúvida registrada.</div>'}</div>`;document.querySelector('#doubtForm').onsubmit=async e=>{e.preventDefault();if(!ens.length)return toast('Você precisa estar matriculado em um curso.');const {error}=await sb.from('doubts').insert({course_id:document.querySelector('#dCourse').value,user_id:state.session.user.id,subject:document.querySelector('#dSubject').value.trim(),body:document.querySelector('#dBody').value.trim()});toast(error?error.message:'Dúvida enviada.');if(!error)renderStudentView(ens,events)};return}if(state.studentView==='forum'){const courseIds=ens.map(e=>e.course_id);let threads=[];if(courseIds.length){const {data}=await sb.from('forum_threads').select('*,profiles!forum_threads_author_id_fkey(full_name)').in('course_id',courseIds).order('created_at',{ascending:false});threads=data||[]}el.innerHTML=`<div class="dash-head"><div><div class="eyebrow">Comunidade</div><h1>Fórum</h1></div></div>${ens.length?`<form class="panel" id="threadForm"><div class="field"><label>Curso</label><select id="fCourse">${ens.map(e=>`<option value="${e.course_id}">${esc(e.courses.title)}</option>`).join('')}</select></div><div class="field"><label>Título</label><input id="fTitle" required></div><div class="field"><label>Mensagem</label><textarea id="fBody" required></textarea></div><button class="btn">Criar tópico</button></form>`:''}<div class="panel">${threads.length?threads.map(t=>`<div class="forum-thread"><h4>${esc(t.title)}</h4><p>${esc(t.body)}</p><div class="hint">${esc(t.profiles?.full_name||'Aluno')} · ${new Date(t.created_at).toLocaleDateString('pt-BR')}</div></div>`).join(''):'<div class="empty">Nenhum tópico ainda.</div>'}</div>`;document.querySelector('#threadForm')?.addEventListener('submit',async e=>{e.preventDefault();const {error}=await sb.from('forum_threads').insert({course_id:document.querySelector('#fCourse').value,author_id:state.session.user.id,title:document.querySelector('#fTitle').value.trim(),body:document.querySelector('#fBody').value.trim()});toast(error?error.message:'Tópico criado.');if(!error)renderStudentView(ens,events)});return}if(state.studentView==='notifications'){const {data}=await sb.from('notifications').select('*').eq('user_id',state.session.user.id).order('created_at',{ascending:false});el.innerHTML=`<div class="dash-head"><div><div class="eyebrow">Notificações</div><h1>Atualizações</h1></div></div><div class="panel">${data?.length?data.map(n=>`<div class="material"><div><b>${esc(n.title)}</b><div class="hint">${esc(n.body||'')} · ${dateTime(n.created_at)}</div></div>${n.link?`<a class="btn small" href="${esc(n.link)}">Abrir</a>`:''}</div>`).join(''):'<div class="empty">Nenhuma notificação.</div>'}</div>`}}
async function openLearning(courseId){if(!await requireUser())return;const {data:access}=await sb.from('enrollments').select('id').eq('user_id',state.session.user.id).eq('course_id',courseId).in('status',['active','completed']).limit(1);if(state.profile?.role!=='admin'&&!access?.length)return toast('Este curso não está liberado para sua conta.');const {data:course}=await sb.from('courses').select('*').eq('id',courseId).single();const {data:mods}=await sb.from('course_modules').select('*').eq('course_id',courseId).order('position');const {data:lessons}=await sb.from('lessons').select('*').in('module_id',(mods||[]).map(m=>m.id)).eq('published',true).order('position');const {data:progress}=await sb.from('lesson_progress').select('*').eq('user_id',state.session.user.id).in('lesson_id',(lessons||[]).map(l=>l.id));state.learning={course,mods:mods||[],lessons:lessons||[],progress:progress||[],selected:(lessons||[])[0]?.id};renderLearning()}
function renderLearning(){const L=state.learning;if(!L)return;const prog=new Map(L.progress.map(p=>[p.lesson_id,p]));const nav=L.mods.map(m=>`<div class="learn-module"><h3>${esc(m.title)}</h3>${L.lessons.filter(l=>l.module_id===m.id).map(l=>`<button class="learn-lesson ${L.selected===l.id?'active':''}" data-lesson="${l.id}"><span class="dot ${prog.get(l.id)?.completed?'done':''}">${prog.get(l.id)?.completed?'✓':''}</span><span>${esc(l.title)}${l.type==='live'?'<br><small>AULA AO VIVO</small>':l.type==='hybrid'?'<br><small>AO VIVO + GRAVAÇÃO</small>':''}</span></button>`).join('')}</div>`).join('');app.innerHTML=header()+`<main class="learning"><aside class="learning-nav"><button class="btn light small" id="backStudent">← Área do aluno</button><h2>${esc(L.course.title)}</h2>${nav}</aside><section class="lesson-main" id="lessonMain"></section></main>`+footer();bindGlobal();document.querySelector('#backStudent').onclick=()=>go(state.profile?.role==='admin'?'admin':'aluno');document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{L.selected=b.dataset.lesson;renderLearning()});renderLesson()}
async function renderLesson(){const L=state.learning,l=L.lessons.find(x=>x.id===L.selected),el=document.querySelector('#lessonMain');if(!l||!el)return;const p=L.progress.find(x=>x.lesson_id===l.id);const {data:mats}=await sb.from('materials').select('*').or(`lesson_id.eq.${l.id},course_id.eq.${L.course.id}`).order('position');let media='';if(l.type==='live'&&!l.recording_url){media=`<div class="live-box"><div class="eyebrow">Aula ao vivo</div><div class="live-time">${dateTime(l.live_starts_at)}</div><p class="sans">${l.live_ends_at?`Previsão de término: ${dateTime(l.live_ends_at)}`:''}</p>${l.live_url?`<a class="btn" href="${esc(l.live_url)}" target="_blank">Entrar no Google Meet</a>`:'<span class="hint">O link será liberado pela coordenação.</span>'}</div>`}else if(l.recording_url||l.video_url){const u=l.recording_url||l.video_url;media=`<div class="lesson-media">${/youtube|youtu\.be|vimeo|drive\.google/.test(u)?`<iframe src="${esc(u)}" allowfullscreen></iframe>`:`<video src="${esc(u)}" controls preload="metadata"></video>`}</div>${l.type==='hybrid'&&l.live_starts_at?`<div class="notice">Esta aula foi ministrada ao vivo em ${dateTime(l.live_starts_at)} e a gravação está disponível.</div>`:''}`}else media=`<div class="lesson-media"><div><b>Conteúdo da aula</b><br><span class="hint" style="color:#aaa">Aula sem vídeo gravado. A coordenação poderá torná-la ao vivo ou anexar uma gravação.</span></div></div>`;el.innerHTML=`<div class="eyebrow">${esc(l.type)} · ${l.duration_minutes||'—'} min</div><h1>${esc(l.title)}</h1>${media}${l.description?`<div class="panel"><p>${esc(l.description)}</p></div>`:''}<div class="panel"><h3>Materiais</h3><div class="material-list">${mats?.length?mats.map(m=>`<div class="material"><div><b>${esc(m.title)}</b><div class="hint">${esc(m.mime_type||'material')}</div></div><a class="btn small" href="${esc(m.file_url)}" target="_blank">Abrir</a></div>`).join(''):'<div class="empty">Nenhum material vinculado a esta aula.</div>'}</div></div><div class="panel"><button class="btn ${p?.completed?'light':''}" id="completeLesson">${p?.completed?'✓ Aula concluída':'Marcar como concluída'}</button></div>`;document.querySelector('#completeLesson').onclick=async()=>{const completed=!p?.completed;const {error}=await sb.from('lesson_progress').upsert({user_id:state.session.user.id,lesson_id:l.id,completed,completed_at:completed?new Date().toISOString():null,updated_at:new Date().toISOString()},{onConflict:'user_id,lesson_id'});if(error)return toast(error.message);const existing=L.progress.find(x=>x.lesson_id===l.id);if(existing)Object.assign(existing,{completed,completed_at:completed?new Date().toISOString():null});else L.progress.push({lesson_id:l.id,completed});renderLearning()}}
async function adminPortal(){if(!await requireUser())return;if(state.profile?.role!=='admin')return go('aluno');shell(`<main class="portal"><aside class="sidebar"><div class="side-title"><span class="brandmark" style="border-color:#fff">WT</span><div><b>Painel WT</b><div class="hint" style="color:#aaa">Administrador</div></div></div><nav><button class="active" data-aview="dashboard">Dashboard</button><button data-aview="students">Alunos</button><button data-aview="courses">Cursos</button><button data-aview="lessons">Aulas</button><button data-aview="agenda">Agenda</button><button data-aview="doubts">Dúvidas</button><button data-aview="publications">Publicações</button><button data-aview="tea">TEA Rio</button><button data-aview="payments">Pagamentos</button></nav><button class="logout" id="logoutAdmin">Sair</button></aside><section class="portal-main" id="adminMain"><div class="loader">Carregando painel…</div></section></main>`);document.querySelector('#logoutAdmin').onclick=logout;document.querySelectorAll('[data-aview]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-aview]').forEach(x=>x.classList.toggle('active',x===b));state.adminView=b.dataset.aview;renderAdminView()});renderAdminView()}
async function renderAdminView(){const el=document.querySelector('#adminMain');if(!el)return;el.innerHTML='<div class="loader">Carregando…</div>';if(state.adminView==='dashboard'){const [{count:students},{count:enrollments},{count:payments},{count:courses}]=await Promise.all([sb.from('profiles').select('*',{count:'exact',head:true}).eq('role','student'),sb.from('enrollments').select('*',{count:'exact',head:true}).eq('status','active'),sb.from('payments').select('*',{count:'exact',head:true}).eq('status','approved'),sb.from('courses').select('*',{count:'exact',head:true})]);el.innerHTML=`<div class="dash-head"><div><div class="eyebrow">Administração</div><h1>Painel WT</h1></div></div><div class="stat-grid"><div class="stat"><b>${students||0}</b><span>Alunos</span></div><div class="stat"><b>${enrollments||0}</b><span>Matrículas ativas</span></div><div class="stat"><b>${courses||0}</b><span>Cursos</span></div><div class="stat"><b>${payments||0}</b><span>Pagamentos aprovados</span></div></div><div class="panel"><h2>Ações rápidas</h2><div class="hero-actions"><button class="btn" data-admin-go="students">Matricular aluno / cortesia</button><button class="btn light" data-admin-go="lessons">Criar ou editar aula</button><button class="btn light" data-admin-go="agenda">Agendar ao vivo</button><button class="btn light" data-admin-go="publications">Publicar conteúdo</button></div></div>`;document.querySelectorAll('[data-admin-go]').forEach(b=>b.onclick=()=>{state.adminView=b.dataset.adminGo;document.querySelectorAll('[data-aview]').forEach(x=>x.classList.toggle('active',x.dataset.aview===state.adminView));renderAdminView()});return}if(state.adminView==='students'){const {data:students}=await sb.from('profiles').select('*').eq('role','student').order('created_at',{ascending:false});const {data:courses}=await sb.from('courses').select('id,title').order('title');const {data:ens}=await sb.from('enrollments').select('*,profiles(full_name,email),courses(title)').order('created_at',{ascending:false}).limit(200);el.innerHTML=`<div class="dash-head"><div><div class="eyebrow">Gestão</div><h1>Alunos e matrículas</h1></div></div><div class="drawer-grid"><form class="panel" id="inviteForm"><h3>Convidar / liberar curso</h3><div class="field"><label>Nome</label><input id="iName"></div><div class="field"><label>E-mail</label><input id="iEmail" type="email" required></div><div class="field"><label>Curso</label><select id="iCourse"><option value="">Somente convidar</option>${(courses||[]).map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('')}</select></div><div class="field"><label>Forma</label><select id="iSource"><option value="courtesy">Cortesia</option><option value="scholarship">Bolsa integral</option><option value="manual_free">Gratuito manual</option></select></div><div class="field"><label>Acesso em dias (vazio = sem data final)</label><input id="iDays" type="number" min="1"></div><div class="field"><label>Observação</label><textarea id="iNote"></textarea></div><button class="btn">Convidar e liberar</button><div id="inviteMsg"></div></form><div class="panel"><h3>Alunos cadastrados</h3>${students?.length?students.map(s=>`<div class="material"><div><b>${esc(s.full_name||'Sem nome')}</b><div class="hint">${esc(s.email)}</div></div></div>`).join(''):'<div class="empty">Nenhum aluno cadastrado.</div>'}</div></div><div class="panel"><h3>Matrículas</h3><div class="table-wrap"><table class="table"><thead><tr><th>Aluno</th><th>Curso</th><th>Origem</th><th>Status</th><th>Valor</th><th>Acesso</th></tr></thead><tbody>${(ens||[]).map(e=>`<tr><td>${esc(e.profiles?.full_name||e.profiles?.email)}</td><td>${esc(e.courses?.title)}</td><td>${esc(e.source)}</td><td>${esc(e.status)}</td><td>${money(e.amount_cents)}</td><td>${e.access_ends_at?dateTime(e.access_ends_at):'Sem data final'}</td></tr>`).join('')}</tbody></table></div></div>`;document.querySelector('#inviteForm').onsubmit=async e=>{e.preventDefault();const msg=document.querySelector('#inviteMsg');msg.textContent='Processando…';const body={email:document.querySelector('#iEmail').value.trim(),full_name:document.querySelector('#iName').value.trim(),course_id:document.querySelector('#iCourse').value||null,source:document.querySelector('#iSource').value,access_days:document.querySelector('#iDays').value?Number(document.querySelector('#iDays').value):null,note:document.querySelector('#iNote').value.trim()||null};const {data,error}=await sb.functions.invoke('admin-invite-student',{body});if(error||data?.error){msg.className='error';msg.textContent=data?.message||data?.error||error?.message}else{msg.className='success';msg.textContent=data.invited?'Convite enviado e acesso configurado.':'Acesso configurado para aluno existente.';setTimeout(renderAdminView,700)}};return}if(state.adminView==='courses'){const {data:courses}=await sb.from('courses').select('*').order('created_at');el.innerHTML=`<div class="dash-head"><div><div class="eyebrow">Catálogo</div><h1>Cursos</h1></div></div><div class="panel"><h3>Cursos cadastrados</h3>${(courses||[]).map(c=>{const p=currentPrice(c);return `<div class="material"><div><b>${esc(c.title)}</b><div class="hint">${c.workload_hours}h · ${money(c.regular_price_cents)} · promoção ${c.sale_price_cents!==null?money(c.sale_price_cents):'—'}</div></div><button class="btn small" data-edit-course="${c.id}">Editar preço</button></div>`}).join('')}</div><form class="panel" id="newCourse"><h3>Novo curso</h3><div class="form-grid"><div class="field wide"><label>Título</label><input id="ncTitle" required></div><div class="field"><label>Carga horária</label><input id="ncHours" type="number" step=".5" required></div><div class="field"><label>Preço normal (R$)</label><input id="ncRegular" type="number" step=".01" required></div><div class="field"><label>Preço promocional (R$)</label><input id="ncSale" type="number" step=".01"></div><div class="field"><label>Parcelas máximas</label><input id="ncInstallments" type="number" min="1" max="24" value="10"></div><div class="field wide"><label>Descrição</label><textarea id="ncDescription"></textarea></div></div><button class="btn">Criar curso</button></form>`;document.querySelectorAll('[data-edit-course]').forEach(b=>b.onclick=async()=>{const c=(courses||[]).find(x=>x.id===b.dataset.editCourse);const regular=prompt('Preço normal em R$',(c.regular_price_cents/100).toFixed(2));if(regular===null)return;const sale=prompt('Preço promocional em R$ (0 para remover)',c.sale_price_cents?(c.sale_price_cents/100).toFixed(2):'0');const inst=prompt('Máximo de parcelas',c.installment_max||10);const {error}=await sb.rpc('set_course_pricing',{p_course_id:c.id,p_regular_cents:Math.round(Number(regular)*100),p_sale_cents:Number(sale)>0?Math.round(Number(sale)*100):null,p_installments:Number(inst)});toast(error?error.message:'Preço atualizado.');if(!error){state.courses=[];await loadCourses();renderAdminView()}});document.querySelector('#newCourse').onsubmit=async e=>{e.preventDefault();const title=document.querySelector('#ncTitle').value.trim(),sale=Number(document.querySelector('#ncSale').value||0);const {error}=await sb.from('courses').insert({title,slug:slugify(title)+'-'+Date.now().toString().slice(-5),description:document.querySelector('#ncDescription').value.trim(),workload_hours:Number(document.querySelector('#ncHours').value),status:'published',regular_price_cents:Math.round(Number(document.querySelector('#ncRegular').value)*100),sale_price_cents:sale>0?Math.round(sale*100):null,installment_max:Number(document.querySelector('#ncInstallments').value),coordinator_name:'Walef Lincoln de Souza Teixeira',coordinator_registration:'CRP 05/85580'});toast(error?error.message:'Curso criado.');if(!error){state.courses=[];await loadCourses();renderAdminView()}};return}if(state.adminView==='lessons'){const {data:courses}=await sb.from('courses').select('id,title').order('title');const first=courses?.[0]?.id;const {data:mods}=first?await sb.from('course_modules').select('*').eq('course_id',first).order('position'):{data:[]};const modIds=(mods||[]).map(m=>m.id);const {data:lessons}=modIds.length?await sb.from('lessons').select('*,course_modules(title)').in('module_id',modIds).order('position'):{data:[]};el.innerHTML=`<div class="dash-head"><div><div class="eyebrow">Conteúdo pedagógico</div><h1>Aulas</h1></div></div><div class="notice">Cada aula pode ser gravada, ao vivo, híbrida ou atividade. Para uma aula ao vivo, basta selecionar a aula, data/horário e colar o link do Google Meet.</div><div class="drawer-grid"><form class="panel" id="moduleForm"><h3>Novo módulo</h3><div class="field"><label>Curso</label><select id="mCourse">${(courses||[]).map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('')}</select></div><div class="field"><label>Título</label><input id="mTitle" required></div><div class="field"><label>Posição</label><input id="mPos" type="number" value="1"></div><div class="field"><label>Carga horária</label><input id="mHours" type="number" step=".5" value="1"></div><button class="btn">Criar módulo</button></form><form class="panel" id="lessonForm"><h3>Nova aula</h3><div class="field"><label>Módulo</label><select id="lModule">${(mods||[]).map(m=>`<option value="${m.id}">${esc(m.title)}</option>`).join('')}</select></div><div class="field"><label>Título</label><input id="lTitle" required></div><div class="field"><label>Tipo</label><select id="lType"><option value="recorded">Gravada</option><option value="live">Ao vivo</option><option value="hybrid">Híbrida</option><option value="activity">Atividade</option></select></div><div class="field"><label>Duração (min)</label><input id="lDuration" type="number" value="60"></div><div class="field"><label>Posição</label><input id="lPos" type="number" value="1"></div><button class="btn">Criar aula</button></form></div><div class="panel"><h3>Aulas do primeiro curso</h3>${(lessons||[]).map(l=>`<div class="material"><div><b>${esc(l.title)}</b><div class="hint">${esc(l.course_modules?.title)} · ${esc(l.type)}${l.live_starts_at?' · '+dateTime(l.live_starts_at):''}</div></div><div><button class="btn small" data-live="${l.id}">Ao vivo / Meet</button> <button class="btn light small" data-rec="${l.id}">Gravação</button></div></div>`).join('')}</div>`;document.querySelector('#moduleForm').onsubmit=async e=>{e.preventDefault();const {error}=await sb.from('course_modules').insert({course_id:document.querySelector('#mCourse').value,title:document.querySelector('#mTitle').value.trim(),position:Number(document.querySelector('#mPos').value),workload_hours:Number(document.querySelector('#mHours').value)});toast(error?error.message:'Módulo criado.');if(!error)renderAdminView()};document.querySelector('#lessonForm').onsubmit=async e=>{e.preventDefault();const type=document.querySelector('#lType').value;const obj={module_id:document.querySelector('#lModule').value,title:document.querySelector('#lTitle').value.trim(),type,position:Number(document.querySelector('#lPos').value),duration_minutes:Number(document.querySelector('#lDuration').value),published:true};if(type==='live'||type==='hybrid'){obj.type='recorded'}const {error}=await sb.from('lessons').insert(obj);toast(error?error.message:'Aula criada. Use “Ao vivo / Meet” para agendar quando necessário.');if(!error)renderAdminView()};document.querySelectorAll('[data-live]').forEach(b=>b.onclick=async()=>{const dt=prompt('Data e horário (ex.: 2026-08-22T19:00)');if(!dt)return;const end=prompt('Término (opcional, ex.: 2026-08-22T21:00)')||null;const url=prompt('Cole o link do Google Meet');if(!url)return;const {error}=await sb.rpc('configure_live_lesson',{p_lesson_id:b.dataset.live,p_starts_at:new Date(dt).toISOString(),p_ends_at:end?new Date(end).toISOString():null,p_meet_url:url});toast(error?error.message:'Aula ao vivo configurada.');if(!error)renderAdminView()});document.querySelectorAll('[data-rec]').forEach(b=>b.onclick=async()=>{const url=prompt('URL da gravação');if(!url)return;const {error}=await sb.rpc('attach_lesson_recording',{p_lesson_id:b.dataset.rec,p_recording_url:url});toast(error?error.message:'Gravação anexada.');if(!error)renderAdminView()});return}if(state.adminView==='agenda'){const {data:ev}=await sb.from('calendar_events').select('*').order('starts_at',{ascending:false}).limit(100);el.innerHTML=`<div class="dash-head"><div><div class="eyebrow">Agenda</div><h1>Eventos e aulas ao vivo</h1></div></div><div class="panel">${ev?.length?ev.map(x=>`<div class="material"><div><b>${esc(x.title)}</b><div class="hint">${dateTime(x.starts_at)}${x.meeting_url?' · Meet configurado':''}</div></div>${x.meeting_url?`<a class="btn small" href="${esc(x.meeting_url)}" target="_blank">Abrir Meet</a>`:''}</div>`).join(''):'<div class="empty">Nenhum evento.</div>'}</div>`;return}if(state.adminView==='doubts'){const {data:d}=await sb.from('doubts').select('*,profiles(full_name,email),courses(title)').order('created_at',{ascending:false});el.innerHTML=`<div class="dash-head"><div><div class="eyebrow">Atendimento acadêmico</div><h1>Dúvidas dos alunos</h1></div></div><div class="panel">${d?.length?d.map(x=>`<div class="forum-thread"><div class="eyebrow">${esc(x.courses?.title||'Curso')} · ${esc(x.status)}</div><h4>${esc(x.subject)}</h4><p>${esc(x.body)}</p><div class="hint">${esc(x.profiles?.full_name||x.profiles?.email)}</div>${x.official_reply?`<p><b>Resposta oficial:</b> ${esc(x.official_reply)}</p>`:`<button class="btn small" data-reply="${x.id}">Responder</button>`}</div>`).join(''):'<div class="empty">Nenhuma dúvida pendente.</div>'}</div>`;document.querySelectorAll('[data-reply]').forEach(b=>b.onclick=async()=>{const text=prompt('Resposta oficial');if(!text)return;const {error}=await sb.from('doubts').update({official_reply:text,status:'answered',replied_by:state.session.user.id,replied_at:new Date().toISOString()}).eq('id',b.dataset.reply);toast(error?error.message:'Respondido.');if(!error)renderAdminView()});return}if(state.adminView==='publications'){const {data:pub}=await sb.from('publications').select('*').order('created_at',{ascending:false});el.innerHTML=`<div class="dash-head"><div><div class="eyebrow">Editorial</div><h1>Publicações</h1></div></div><form class="panel" id="pubForm"><div class="form-grid"><div class="field"><label>Tipo</label><select id="pType"><option value="article">Artigo</option><option value="news">Notícia</option><option value="video">Vídeo</option></select></div><div class="field"><label>Título</label><input id="pTitle" required></div><div class="field wide"><label>Resumo</label><textarea id="pExcerpt"></textarea></div><div class="field wide"><label>Texto</label><textarea id="pBody"></textarea></div><div class="field"><label>URL de mídia</label><input id="pMedia" type="url"></div><div class="field"><label>Status</label><select id="pStatus"><option value="published">Publicado</option><option value="draft">Rascunho</option></select></div></div><button class="btn">Salvar publicação</button></form><div class="panel">${pub?.length?pub.map(x=>`<div class="material"><div><b>${esc(x.title)}</b><div class="hint">${esc(x.type)} · ${esc(x.status)}</div></div></div>`).join(''):'<div class="empty">Nenhuma publicação.</div>'}</div>`;document.querySelector('#pubForm').onsubmit=async e=>{e.preventDefault();const status=document.querySelector('#pStatus').value,title=document.querySelector('#pTitle').value.trim();const {error}=await sb.from('publications').insert({type:document.querySelector('#pType').value,title,slug:slugify(title)+'-'+Date.now().toString().slice(-6),excerpt:document.querySelector('#pExcerpt').value.trim(),body:document.querySelector('#pBody').value.trim(),media_url:document.querySelector('#pMedia').value.trim()||null,status,published_at:status==='published'?new Date().toISOString():null});toast(error?error.message:'Publicação salva.');if(!error)renderAdminView()};return}if(state.adminView==='tea'){const {data:items}=await sb.from('tea_rio_items').select('*').order('position');el.innerHTML=`<div class="dash-head"><div><div class="eyebrow">Projeto</div><h1>TEA Rio</h1></div></div><form class="panel" id="teaForm"><div class="form-grid"><div class="field"><label>Tipo</label><select id="tKind"><option value="acao">Ação</option><option value="formacao">Formação</option><option value="noticia">Notícia</option><option value="galeria">Galeria</option></select></div><div class="field"><label>Título</label><input id="tTitle" required></div><div class="field wide"><label>Texto</label><textarea id="tBody"></textarea></div><div class="field"><label>URL da mídia</label><input id="tMedia" type="url"></div><div class="field"><label>Data</label><input id="tDate" type="date"></div><div class="field"><label>Posição</label><input id="tPos" type="number" value="1"></div></div><button class="btn">Publicar no TEA Rio</button></form><div class="panel">${items?.length?items.map(x=>`<div class="material"><div><b>${esc(x.title)}</b><div class="hint">${esc(x.kind)} · ${esc(x.status)}</div></div></div>`).join(''):'<div class="empty">Os registros institucionais podem ser cadastrados aqui.</div>'}</div>`;document.querySelector('#teaForm').onsubmit=async e=>{e.preventDefault();const {error}=await sb.from('tea_rio_items').insert({kind:document.querySelector('#tKind').value,title:document.querySelector('#tTitle').value.trim(),body:document.querySelector('#tBody').value.trim(),media_url:document.querySelector('#tMedia').value.trim()||null,event_date:document.querySelector('#tDate').value||null,position:Number(document.querySelector('#tPos').value),status:'published'});toast(error?error.message:'Conteúdo publicado no TEA Rio.');if(!error)renderAdminView()};return}if(state.adminView==='payments'){const {data:pays}=await sb.from('payments').select('*,profiles(full_name,email),courses(title)').order('created_at',{ascending:false}).limit(200);el.innerHTML=`<div class="dash-head"><div><div class="eyebrow">Financeiro</div><h1>Pagamentos</h1></div></div><div class="panel"><div class="notice">Pagamentos do Mercado Pago aparecerão automaticamente após a integração receber as notificações do provedor. Cortesias e bolsas ficam registradas com valor zero.</div><div class="table-wrap"><table class="table"><thead><tr><th>Aluno</th><th>Curso</th><th>Status</th><th>Valor</th><th>Provedor</th><th>Data</th></tr></thead><tbody>${(pays||[]).map(p=>`<tr><td>${esc(p.profiles?.full_name||p.profiles?.email||'—')}</td><td>${esc(p.courses?.title||'—')}</td><td>${esc(p.status)}</td><td>${money(p.amount_cents)}</td><td>${esc(p.provider)}</td><td>${new Date(p.created_at).toLocaleDateString('pt-BR')}</td></tr>`).join('')}</tbody></table></div></div>`}}
async function teaPage(){shell(`<main class="page"><section class="page-hero dark"><div class="wrap"><div class="eyebrow" style="color:#aaa">Projeto</div><h1>TEA Rio</h1><p class="sans" style="max-width:760px;color:#bbb">Ações, formações e registros institucionais do projeto.</p></div></section><section class="section dark"><div class="wrap tea-grid"><div class="gallery"><div class="photo tea-one"></div><div class="photo tea-two"></div><div class="photo tea-four"></div></div><div><h2 style="font-size:48px;line-height:1">Formação, orientação e participação.</h2><p class="sans" style="color:#bbb">O Projeto TEA Rio reúne iniciativas de formação e orientação para famílias, professores e contextos educacionais. Os registros publicados nesta área são administrados diretamente pelo Painel WT.</p><a class="btn light" href="https://wa.me/5521988631632?text=Ol%C3%A1%2C%20quero%20saber%20mais%20sobre%20o%20Projeto%20TEA%20Rio." target="_blank">Falar sobre o projeto</a></div></div></section><section class="section white"><div class="wrap"><div class="head"><div><div class="eyebrow">Acervo</div><h2>Ações do projeto</h2></div></div><div id="teaItems" class="cards"><div class="loader">Carregando…</div></div></div></section></main>`);const {data}=await sb.from('tea_rio_items').select('*').eq('status','published').order('position');const el=document.querySelector('#teaItems');el.innerHTML=data?.length?data.map(x=>`<article class="card"><div class="eyebrow">${esc(x.kind)}</div><h3>${esc(x.title)}</h3><p>${esc(x.body||'')}</p>${x.media_url?`<a class="btn light small" href="${esc(x.media_url)}" target="_blank">Ver registro</a>`:''}</article>`).join(''):'<div class="empty">Novos registros serão publicados pela administração do projeto.</div>'}
function aboutPage(){shell(`<main class="page"><section class="page-hero"><div class="wrap"><div class="eyebrow">Trajetória</div><h1>Walef Teixeira</h1><p class="sans">Psicólogo — CRP 05/85580</p></div></section><section class="section soft"><div class="wrap about-grid"><div class="portrait-photo"></div><div class="about-copy"><h2>Atuação profissional e produção.</h2><p>Psicologia, Análise do Comportamento, formação profissional, tecnologia aplicada e projetos de educação e orientação constituem os eixos desta plataforma.</p><div class="timeline"><div><b>Psicologia</b><p>Atuação profissional com registro ativo no Conselho Regional de Psicologia.</p></div><div><b>Análise do Comportamento</b><p>Estudo, aplicação e formação orientados por princípios científicos e ética profissional.</p></div><div><b>Formação</b><p>Desenvolvimento de cursos, materiais, aulas e capacitações.</p></div><div><b>Projeto TEA Rio</b><p>Iniciativa voltada a ações de formação e orientação em contextos familiares e educacionais.</p></div></div></div></div></section></main>`)}
function contentPage(){shell(`<main class="page"><section class="page-hero"><div class="wrap"><div class="eyebrow">Conteúdo</div><h1>Artigos, notícias e vídeos</h1></div></section><section class="section"><div class="wrap"><div id="allPub" class="cards"><div class="loader">Carregando…</div></div></div></section></main>`);sb.from('publications').select('*').eq('status','published').order('published_at',{ascending:false}).then(({data})=>{document.querySelector('#allPub').innerHTML=data?.length?data.map(x=>`<article class="card"><div class="eyebrow">${esc(x.type)}</div><h3>${esc(x.title)}</h3><p>${esc(x.excerpt||x.body||'')}</p>${x.media_url?`<a class="btn light small" target="_blank" href="${esc(x.media_url)}">Abrir</a>`:''}</article>`).join(''):'<div class="empty">Nenhuma publicação ainda.</div>'})}
function certPage(){shell(`<main class="auth-shell"><section class="auth-card"><div class="eyebrow">Autenticidade</div><h1>Verificar certificado</h1><p class="sans" style="color:#666">Digite o código de autenticação informado no certificado.</p><form id="certForm"><div class="field"><label>Código</label><input id="certCode" required></div><button class="btn" style="width:100%">Verificar</button></form><div id="certResult"></div></section></main>`);document.querySelector('#certForm').onsubmit=async e=>{e.preventDefault();const {data,error}=await sb.rpc('verify_certificate',{p_code:document.querySelector('#certCode').value.trim()});const el=document.querySelector('#certResult');if(error||!data?.length)el.innerHTML='<div class="cert-result"><b>Certificado não localizado.</b></div>';else{const c=data[0];el.innerHTML=`<div class="cert-result"><div class="eyebrow">${esc(c.status)}</div><h3>${esc(c.course_title)}</h3><p class="sans"><b>Aluno:</b> ${esc(c.student_name)}<br><b>Número:</b> ${esc(c.certificate_number)}<br><b>Emissão:</b> ${dateTime(c.issued_at)}</p></div>`}}}
async function route(){await loadIdentity();if(!state.courses.length)await loadCourses();const raw=location.hash.replace(/^#/,'')||'home';state.route=raw;if(raw==='home'||raw==='cursos'||raw==='contato'){home();setTimeout(()=>{const id=raw==='cursos'?'cursos':raw==='contato'?'contato':null;if(id)document.getElementById(id)?.scrollIntoView()},30);return}if(raw.startsWith('curso/'))return publicCourse(decodeURIComponent(raw.split('/').slice(1).join('/')));if(raw==='entrar')return state.session?go(state.profile?.role==='admin'?'admin':'aluno'):loginPage();if(raw==='aluno')return studentPortal();if(raw==='admin')return adminPortal();if(raw==='tea-rio')return teaPage();if(raw==='sobre')return aboutPage();if(raw==='conteudos')return contentPage();if(raw==='certificado')return certPage();home()}
window.addEventListener('hashchange',route);sb.auth.onAuthStateChange(()=>setTimeout(route,0));route();